    'list_the_hooks_called_during_sign_in_and_token_issuance_563aad82' => 'Zobrazenie hookov volaných pri prihlásení a vydávaní tokenov a informácie, či sú aktívne.',
    'list_the_siem_destinations_this_environment_s_audit_tra_fe43c8df' => 'Zobrazenie cieľov SIEM, do ktorých sa odosiela auditný záznam tohto prostredia, a informácie, či sú povolené.',
    'read_this_environment_s_domain_events_the_same_events_w_a994d958' => 'Čítanie doménových udalostí tohto prostredia — rovnakých, aké doručujú webhooky — pomocou kurzora.',
