    'register_repoint_pause_resume_re_key_and_delete_webhook_59f2b3cf' => 'Registrácia koncových bodov webhookov, zmena cieľa, pozastavenie, obnovenie, výmena kľúčov a odstránenie. Nové alebo vymenené podpisové tajomstvo sa zobrazí iba raz.',
    'register_pause_activate_and_remove_hooks_endpoints_that_17dc8c62' => 'Registrácia, pozastavenie, aktivácia a odstránenie hookov — koncových bodov, ktoré môžu pridávať atribúty do tokenov alebo odmietnuť prihlásenie.',
    'create_disable_resume_and_delete_audit_log_streams_a_ge_d507a36c' => 'Vytváranie, vypínanie, obnovenie a odstránenie streamov auditných záznamov. Vygenerovaný podpisový kľúč sa zobrazí iba raz.',
    'record_audit_events_your_app_s_users_cause_for_the_orga_a94adc1d' => 'Zaznamenávanie auditných udalostí vyvolaných používateľmi vašej aplikácie pre organizácie, v ktorých nastali. Iba oprávnenia potrebné pre backend odosielajúci udalosti.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Čítanie auditných udalostí odoslaných vašou aplikáciou a ich exportov, overenie reťazca organizácie a čítanie schém a pravidiel uchovávania týchto udalostí.',
    'start_csv_exports_of_the_audit_events_your_app_sent_the_230b66c5' => 'Spustenie exportu auditných udalostí odoslaných vašou aplikáciou do CSV — rovnakých udalostí, ktoré sprístupňuje rozsah na čítanie, v jednom súbore.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Definovanie, nahrádzanie a odstraňovanie schém na validáciu auditných udalostí a zmena doby ich uchovávania — skrátenie tejto doby natrvalo vymaže staršie udalosti.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Čítanie autorizačnej schémy a jej n-tíc a vykonávanie kontrol a dopytov na zoznamy — „Smie tento používateľ upraviť tento dokument?“, „Ktoré dokumenty môže vidieť?“. Iba oprávnenia potrebné pre backend aplikácie na vynucovanie prístupu.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Zápis a mazanie n-tíc vzťahov — kto vlastní, upravuje alebo prezerá ktoré prostriedky vašej aplikácie. Zápis okamžite udeľuje alebo odoberá prístup v aplikácii.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Nahradenie autorizačnej schémy — typov prostriedkov a spôsobu vyhodnocovania jednotlivých vzťahov. Okamžite mení odpovede na všetky kontroly v tomto prostredí.',
    'read_the_authentication_policy_the_social_login_provide_758352e3' => 'Čítanie pravidiel overovania, poskytovateľov sociálneho prihlásenia a deklarácie staršieho prihlasovania — nikdy tajomstva poskytovateľa.',
    'change_password_mfa_and_sso_rules_self_service_sign_up_66c7cb03' => 'Zmena pravidiel hesiel, MFA a SSO, samoobslužnej registrácie, poskytovateľov sociálneho prihlásenia a schválenia staršieho prihlasovania.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Čítanie režimu Radaru, vstavaných a vlastných pravidiel, zoznamov povolených a blokovaných položiek a prehľadu rozhodnutí — prečo bolo prihlásenie či registrácia povolené, podrobené dodatočnému overeniu alebo zablokované. Nikdy nesprístupňuje IP ani inú adresu z rozhodnutia.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Zápis, zmena poradia a mazanie pravidiel Radaru, úprava vstavaných pravidiel a pridávanie či odoberanie položiek zoznamov povolených a blokovaných.',
    'switch_radar_between_monitor_record_only_and_enforce_bl_c3ec2073' => 'Prepínanie Radaru medzi sledovaním (iba záznam) a vynucovaním (blokovanie a dodatočné overovanie) — zapnutie či vypnutie ochrany prihlásenia v prostredí.',
    'list_the_publishable_keys_browser_apps_present_to_the_f_9a4fe3ce' => 'Zobrazenie zverejniteľných kľúčov, ktoré aplikácie v prehliadači predkladajú rozhraniu Frontend API, a ich povolených pôvodov.',
    'create_publishable_keys_change_which_origins_may_presen_79684ec2' => 'Vytváranie zverejniteľných kľúčov, zmena pôvodov, ktoré ich môžu predkladať, a odvolávanie kľúčov.',
    'list_the_applications_that_trust_this_environment_as_th_61538b0b' => 'Zobrazenie aplikácií, ktoré tomuto prostrediu dôverujú ako poskytovateľovi identity SAML — nikdy ich certifikátov.',
    'register_change_and_remove_the_applications_people_sign_6b6a4041' => 'Registrácia, zmena a odstránenie aplikácií, do ktorých sa používatelia prihlasujú pomocou tunajšieho účtu.',
    'read_the_hosted_sign_in_theme_and_branding_of_the_envir_c85a3622' => 'Čítanie motívu a vizuálnej identity hostovaného prihlasovania prostredia a jeho organizácií.',
    'change_the_hosted_sign_in_theme_and_branding_of_the_env_bc832c7e' => 'Zmena motívu a vizuálnej identity hostovaného prihlasovania prostredia a jeho organizácií.',
    'read_this_environment_s_custom_domain_and_the_dns_recor_4408e8a7' => 'Čítanie vlastnej domény tohto prostredia a záznamu DNS, ktorý ju overuje.',
    'add_verify_and_remove_the_custom_domain_this_environmen_9a4835eb' => 'Pridávanie, overovanie a odstraňovanie vlastnej domény, na ktorej je toto prostredie dostupné.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Trvalé vymazanie osoby (čl. 17 GDPR): jej prihlasovacie údaje, relácie, členstvá a osobné údaje sa vymažú a účet sa pseudonymizuje. Nedá sa vrátiť späť.',
    'create_rename_re_permission_and_delete_roles_and_author_dca95601' => 'Vytváranie, premenovanie, zmena oprávnení a mazanie rolí a definovanie ručných oprávnení, z ktorých sa skladajú. Prideľovanie rolí používateľom patrí pod `roles:write`.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Zobrazenie pripojení SAML a OIDC, cez ktoré sa organizácie prihlasujú, a e-mailových domén, ktoré na ne používateľov smerujú — nikdy certifikátov, tajomstiev klienta ani podpisových kľúčov.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Vytváranie, zmena, povoľovanie, zakazovanie a mazanie pripojení SSO, vyžadovanie SSO pre organizáciu a overovanie jej e-mailových domén a vynucovanie SSO pre ne. Mení spôsob prihlasovania používateľov.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Zobrazenie adresárov (SCIM, Google Workspace, Microsoft Entra), z ktorých sa synchronizujú používatelia, ich skupín a chýb synchronizácie — nikdy bearer tokenov ani prihlasovacích údajov poskytovateľa.',
    'connect_rename_pause_re_key_and_delete_inbound_director_9cb4cce4' => 'Pripájanie, premenovanie, pozastavenie, výmena kľúčov a mazanie zdrojových adresárov a mapovanie ich skupín na roly. Nový alebo vymenený SCIM bearer token sa zobrazí iba raz.',
    'list_the_downstream_scim_targets_this_environment_pushe_2753c203' => 'Zobrazenie cieľových systémov SCIM, do ktorých toto prostredie odosiela používateľov, a informácie o prípadných zlyhaniach — nikdy ich prihlasovacích údajov.',
    'register_pause_resume_and_delete_the_scim_targets_this_ca3c3bb1' => 'Registrácia, pozastavenie, obnovenie a mazanie cieľov SCIM, do ktorých toto prostredie odosiela údaje používateľov.',
    'read_role_conflict_segregation_of_duties_rules_and_acce_8572d9a3' => 'Čítanie pravidiel konfliktov rolí (oddelenia povinností) a preskúmaní prístupu vrátane všetkých položiek, ktoré má niekto potvrdiť.',
    'define_switch_and_remove_role_conflict_rules_open_acces_34e40e6c' => 'Definovanie, zapínanie, vypínanie a odstraňovanie pravidiel konfliktov rolí; začínanie preskúmaní prístupu, zaznamenávanie rozhodnutí a uzatváranie preskúmaní — uzatvorenie vykoná všetky odobratia prístupu.',
    'list_the_downstream_credentials_stored_in_the_token_vau_15a080ce' => 'Zobrazenie prihlasovacích údajov pre nadväzujúce systémy uložených v trezore tokenov a aplikácií, ktoré k nim môžu získať dočasný prístup — nikdy uložených hodnôt.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Ukladanie, rotácia a odvolávanie prihlasovacích údajov pre nadväzujúce systémy a udeľovanie či odoberanie práva aplikácie na dočasný prístup k nim. Nejde o rozsahy vault.manage / vault.lease obsiahnuté vo vlastnom tokene aplikácie.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Zobrazenie príznakov funkcií a ich cielenia a vyhodnotenie každého príznaku pre používateľa v organizácii — to, na čo sa backend aplikácie pýta, keď nemá token.',
    'define_switch_retarget_and_delete_feature_flags_which_f_e64692af' => 'Definovanie, prepínanie, zmena cielenia a mazanie príznakov funkcií — ktoré funkcie získajú ktorí používatelia a organizácie.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Zobrazenie externých poskytovateľov, ku ktorým môžu používatelia pripojiť svoje účty, aplikácií s právom dočasného prístupu k týmto tokenom a pripojených používateľov — nikdy tajomstiev klienta ani tokenov.',
    'configure_change_and_remove_pipes_grant_or_withdraw_an_f69a04e9' => 'Konfigurácia, zmena a odstránenie integrácií pipes, udeľovanie alebo odoberanie práva aplikácie na dočasný prístup k tokenom pripojených účtov a odpájanie účtov používateľov.',
