    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Vytváranie a odvolávanie jednorazových odkazov do administračného portálu, ktoré IT správcovi organizácie umožnia nastaviť SSO, domény či synchronizáciu adresárov bez účtu. Nový odkaz sa zobrazí iba raz.',
