    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'Jeho udalosti sa od tejto chvíle prijímajú bez kontroly — alebo sa odmietajú, ak je zapnutý prísny režim.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Jeho členovia sa môžu znova prihlasovať a jeho prostredia obnovia overovanie.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Vlastné prihlasovacie údaje namiesto údajov prostredia pre tohto poskytovateľa.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Kľúč vytvorený. Vložte ho do frontendu — je určený na zverejnenie.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Kľúč obnovený — skopírujte si teraz nový. Starý kľúč funguje ešte 24 hodín.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Na prihlasovacej stránke ponúka tlačidlá Google, GitHub, Apple a ďalších poskytovateľov ľuďom, ktorí uprednostnia existujúci účet pred ďalším heslom. Poskytovateľa nastavíte raz pre prostredie a bude dostupný všetkým organizáciám. Organizácia môže použiť vlastné prihlasovacie údaje alebo poskytovateľa vypnúť. Zadáte prihlasovacie údaje a zvyšok sa vyplní automaticky. Samotná adresa od poskytovateľa nikdy nestačí na prístup k existujúcemu účtu.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Kľúče, ktorými sa váš kód preukazuje službe Cbox ID, so samostatnou kartou pre každý typ. Tajný kľúč, nazývaný aj kľúč na správu, umožňuje backendu spravovať organizácie, členov, pozvánky, roly a aplikácie jedného prostredia. Kľúč organizácie volá jej API so vstavanou rolou. Verejný kľúč sa používa v aplikácii v prehliadači a funguje iba z povolených zdrojov. Tajné kľúče a kľúče organizácie sa zobrazujú iba raz. Pri vytvorení ich skopírujte a pri úniku ich okamžite zrušte.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registruje aplikácie, ktoré prijímajú toto prostredie ako poskytovateľa identity SAML, takže používatelia sa prihlasujú svojimi existujúcimi účtami. Každej aplikácii priraďte jej organizáciu, aby mali prístup len členovia tejto organizácie. Bez priradenej organizácie je aplikácia dostupná všetkým používateľom prostredia. Ide o odchádzajúci smer. Na prihlasovanie firemným účtom z iného systému použite Podnikové SSO v časti Overovanie.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Vyberte framework, v ktorom vyvíjate. Vytvorí sa aplikácia s presmerovaním na miestny vývojový server, blokom konfigurácie prostredia na vloženie a kódom na prihlásenie používateľa. Stránka čaká na skutočné prihlásenie. Nižšie sú kroky prípravy produktu: vizuálna identita, organizácie, jednotné prihlasovanie, agent, kolega a produkčné prostredie. Dokončenie sa označuje podľa skutočného stavu prostredia, nikdy ručne.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar vyhodnocuje každé prihlásenie a registráciu: pokusy s ukradnutými prihlasovacími údajmi, rýchlosť typickú pre boty, nemožné presuny, nové zariadenia, anonymizačné siete a jednorazové adresy aj vaše vlastné pravidlá a zoznamy povolených a blokovaných hodnôt. Zaznamenáva každé rozhodnutie a po zapnutí vynucovania blokuje prístup alebo vyžaduje druhý faktor. Rozhodnutia si tu prezrite pred zapnutím vynucovania aj vtedy, keď sa niekto nemôže prihlásiť.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Prepínače funkcií, na ktoré sa aplikácie pýtajú pre konkrétnu osobu v organizácii. Zapnite funkciu vybraným používateľom, organizáciám alebo časti všetkých používateľov. Každá aplikácia prečíta rovnakú odpoveď z tokenu alebo cez API.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Softvér, ktorý v tomto prostredí vykonáva činnosti pomocou kľúča na správu: Claude Code, Cursor, interný bot alebo váš backend. Každý má iba rozsahy oprávnení, ktoré ste mu pridelili, a tam, kde ste to vyžadovali, čaká na vaše schválenie.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Príjemca používa rovnaký tajný kľúč. Zo 64-znakového hexadecimálneho kľúča vznikne whsec_ nasledované kódovaním base64 tohto hexadecimálneho reťazca — "whsec_" + base64(secret). Kľúč, ktorý sa už začína na whsec_, sa použije bez zmeny.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organizácie, používatelia a aktívne relácie zo všetkých prostredí tejto inštalácie a organizácie s najväčším počtom členov. Tento prehľad iba číta údaje a nikdy nemení prostredie vybrané v konzole.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Všetci, ktorí sa môžu prihlásiť do tejto organizácie, a odoslané pozvánky, ktoré ešte nikto neprijal. Pozvite ľudí e-mailom; prihlásenie si nastavia sami, takže nikdy nemusíte spravovať cudzie heslo.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Umožnite ľuďom prihlásiť sa účtom, ktorý už majú. Poskytovateľa nastavíte raz pre celé prostredie a bude dostupný vo všetkých organizáciách. Organizácia môže použiť vlastné prihlasovacie údaje alebo poskytovateľa vypnúť.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar vyhodnocuje každé prihlásenie a registráciu: pokusy s ukradnutými prihlasovacími údajmi, rýchlosť typickú pre botov, nemožné presuny, nové zariadenia, anonymizačné siete, jednorazové adresy a vaše vlastné pravidlá a zoznamy. Zaznamenáva aj dôvod rozhodnutia.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Tento používateľ sa už nemôže prihlásiť do žiadnej aplikácie v tomto prostredí a jeho existujúce relácie prestanú fungovať pri ďalšej požiadavke. Jeho záznamy zostanú zachované a kedykoľvek ho môžete znova aktivovať.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Vyhodnocuje sa postupne: zoznam blokovaných, zoznam povolených, vlastné pravidlá zhora nadol (rozhodne prvá zhoda) a potom vstavané pravidlá (rozhodne najprísnejšie z tých, ktoré sa uplatnia). Ak sa nič nezhoduje, prístup je povolený.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Väčšina integrácií by mala používať webhooky: spúšťajú sa až po udalosti a nemôžu ju zdržať. Hook použite len vtedy, keď váš systém musí zasiahnuť počas prihlasovania alebo vydávania tokenu.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Tu sa zobrazujú vytvorené kľúče a údaj o ich poslednom použití.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Ponechajte prázdne, ak nechcete uzamykanie — v tomto nasadení je predvolené uzamykanie vypnuté.',
    'let_people_sign_in_with_the_company_account_they_alread_b98aff03' => 'Umožnite ľuďom prihlásiť sa firemným účtom, ktorý už majú, namiesto samostatného hesla tu.',
    'log_stream_saved_delivery_is_tried_again_on_the_next_ru_fb2e3c84' => 'Dátový prúd protokolu bol uložený. Doručenie sa skúsi znova pri ďalšom spustení.',
    'management_key_created_copy_it_now_it_will_not_be_shown_9ec713ad' => 'Kľúč na správu bol vytvorený — skopírujte si ho teraz, znova sa nezobrazí.',
    'map_a_group_onto_the_roles_everyone_in_it_should_hold_m_1a407a38' => 'Namapujte skupinu na roly, ktoré majú mať všetci jej členovia. Členstvo sa synchronizuje a roly sa mu prispôsobujú.',
