    'this_transfers_ownership_of_the_shared_organization_rol_19e09a02' => 'Tým prevediete vlastníctvo zdieľanej organizácie. Roly v jednotlivých aplikáciách zostanú nezmenené; môžete stratiť prístup k Cbox ID.',
