    'the_app_whose_declared_roles_and_permissions_tokens_for_a1169778' => 'Aplikácia, ktorej deklarované roly a oprávnenia obsahujú tokeny pre toto API. Ak ponecháte prázdne, každý token bude obsahovať roly aplikácie, ktorá oň požiadala.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'Aplikácia, ktorej deklarované roly a oprávnenia obsahujú tokeny pre toto API. Vybrať možno iba aplikácie s týmto vlastníkom: :part1.',
    'the_audience_its_tokens_name_fixed_every_token_already_a3d06aee' => 'Príjemca uvedený v jeho tokenoch. Nemenný — obsahuje ho každý už vydaný token.',
    'the_baseline_every_organization_in_this_environment_inh_75711a2d' => 'Základné pravidlá, ktoré dedí každá organizácia tohto prostredia. Organizácia môže požadovať prísnejšie pravidlá, nikdy nie miernejšie.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'Horná hranica prístupu tejto aplikácie. Zúženie sa prejaví od ďalšieho tokenu. Zariadenie alebo agent žiadajúci o odobratý rozsah dostane zamietnutie, nie potichu obmedzený prístup.',
    'the_ceiling_on_this_app_s_tokens_it_can_ask__87966742' => 'Maximálny rozsah prístupu tokenov tejto aplikácie. Aplikácia môže požiadať o menej oprávnení, nikdy však o viac.',
    'the_conflict_stops_being_enforced_grants_it_was_blockin_37391474' => 'Pravidlo konfliktu sa prestane uplatňovať. Pridelenia, ktoré blokovalo, budú opäť možné.',
    'the_conflict_stops_being_enforced_immediately_and_grant_88f978ef' => 'Pravidlo konfliktu sa okamžite prestane uplatňovať a blokované pridelenia budú opäť možné. Túto akciu nemožno vrátiť späť.',
    'the_current_client_secret_stops_working_immediately_and_030370f0' => 'Súčasný tajný kľúč klienta okamžite prestane fungovať a nemožno ho obnoviť — overenie všetkých nasadení, ktoré ho stále používajú, začne zlyhávať.',
    'the_environment_s_administrators_register_apis_and_deci_eb40bdf1' => 'Správcovia prostredia registrujú API a určujú, o ktoré ich rozsahy môžu vaše aplikácie požiadať.',
    'the_facts_your_app_wrote_what_they_add_up_to_is_what_a_3240d92d' => 'Fakty zapísané vašou aplikáciou. Ich výsledný význam určuje odpoveď kontroly.',
    'the_key_can_do_only_what_its_scopes_allow_read_never_im_78fe4757' => 'Kľúč môže robiť iba to, čo povoľujú jeho rozsahy. Čítanie nikdy neznamená zápis.',
    'the_key_holds_the_built_in_role_you_choose_and_can_do_o_b7c48a4b' => 'Kľúč má zvolenú vstavanú rolu a smie robiť iba to, čo táto rola povoľuje.',
    'the_kill_switch_off_the_flag_is_off_for_everyone_whatev_90bda36f' => 'Hlavný vypínač. Ak je vypnutý, príznak je vypnutý pre všetkých bez ohľadu na pravidlá nižšie.',
    'the_organization_the_app_belongs_to_or_regis_d0bd8e48' => 'Organizácia, ktorej aplikácia patrí — alebo ju vyššie zaregistrujte do prostredia.',
    'the_return_address_must_be_on_one_of_app_s_registered_r_20ea9b1f' => 'Návratová adresa musí patriť k niektorému z registrovaných zdrojov URI presmerovania aplikácie :app.',
    'the_rules_in_force_after_this_environment_s_baseline_is_278c536a' => 'Pravidlá platné po uplatnení základných nastavení prostredia. Vlastné nastavenia organizácie ich môžu iba sprísniť.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Vaše služby, ktoré prijímajú prístupové tokeny, a rozsahy oprávnení patriace každej z nich. Rozsahy registrovaného API prideľujete vy — nikto nemôže získať prístup k vášmu API iba napísaním rozsahu do aplikácie.',
    'the_organization_s_own_keys_for_the_organization_api_li_86017b30' => 'Vlastné kľúče organizácie pre jej API: výpis projektov a prostredí, vytváranie prostredí, výpis tímu a pozývanie členov. Každý kľúč má vstavanú rolu.',
    'these_apply_to_every_organization_in_part1_not_only_par_ac56590d' => 'Platia pre všetky organizácie v :part1, nielen pre :part2.',
    'these_are_its_own_credentials_for_that_environment_s_co_a68e7d01' => 'Toto sú jej vlastné prihlasovacie údaje pre konfiguráciu daného prostredia. :part1',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Táto osoba sa stane vlastníkom :part1 a vy správcom. Vlastníctvo vám môže vrátiť iba nový vlastník.',
    'they_become_this_organization_s_only_owner_whoever_owns_11374c6d' => 'Stane sa jediným vlastníkom tejto organizácie. Súčasný vlastník sa stane správcom.',
    'they_get_an_email_with_a_link_nothing_changes_until_the_e94c64b9' => 'Dostane e-mail s odkazom. Kým pozvánku neprijme, nič sa nezmení.',
    'they_lose_access_to_this_organization_and_everything_it_984eedd8' => 'Stratí prístup k tejto organizácii a všetkému, čo poskytuje. Samotný účet zostane nedotknutý.',
    'they_lose_every_role_and_application_this_organization_8c05da9e' => 'Okamžite stratí všetky roly a aplikácie poskytované touto organizáciou.',
    'this_app_belongs_to_the_platform_and_is_available_to_ev_0c69cd5f' => 'Táto aplikácia patrí platforme a je dostupná každej organizácii v tomto prostredí. Spravuje ju váš prevádzkovateľ.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Táto aplikácia má rozsahy viacerých API: :part1 :part2. Token je vždy určený iba jednému API, preto aplikácia uvedie požadované API parametrom :part3 — žiadosť o rozsahy dvoch API naraz sa odmietne.',
    'this_changes_permissions_for_all_current_holders_of_thi_a515eb89' => 'Zmení oprávnenia všetkým súčasným držiteľom tejto roly. Rolu nikomu novému nepridelí.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Toto nasadenie nemá kľúče Turnstile (CBOX_ID_TURNSTILE_SITE_KEY), preto nemožno zapnúť overovaciu výzvu. Označená registrácia namiesto toho vyžaduje overenie e-mailovej adresy.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Toto nasadenie odosiela SMS iba do týchto krajín: :part1. Čísla z nasledujúcich krajín nemôžu dostávať kódy, kým tieto krajiny nebudú zahrnuté v CBOX_ID_SMS_ALLOWED_COUNTRIES: :part2.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'Vlastný vydavateľ tohto prostredia — adresa, z ktorej SDK zisťuje konfiguráciu a ktorú obsahuje pole :part1.',
    'this_is_the_app_s_only_live_secret_so_it_cannot_be_revo_d05986bb' => 'Toto je jediný aktívny tajný kľúč aplikácie, preto ho nemožno samostatne odobrať — aplikácia by zostala bez náhrady a prestala fungovať. Namiesto toho vykonajte rotáciu.',
    'this_member_a802a70b' => 'tento člen',
