    'every_api_key_the_people_in_this_organization_have_crea_b802c1e7' => 'Všetky kľúče API, ktoré ľudia v tejto organizácii vytvorili pre jej aplikácie. Odvolajte kľúč, ktorý unikol alebo sa už nepoužíva. Vlastné kľúče si ľudia vytvárajú v časti Môj účet.',
    'every_logout_token_then_names_the_session_si_54d0a907' => 'Každý odhlasovací token potom obsahuje okrem osoby aj reláciu (sid), takže aplikácia môže ukončiť iba túto reláciu namiesto všetkých.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Všetky odvolania zaznamenané v tejto kontrole sa teraz skutočne vykonajú. Dosiaľ neskontrolované položky sa riadia pravidlami kontroly, ktoré predvolene odvolávajú prístup. Túto akciu nemožno vrátiť späť.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Všetky tajné kľúče, ktoré teraz overujú túto aplikáciu. Ukladá sa iba hash každého z nich. Zoznam ukazuje posledné štyri znaky, aby ste rozpoznali, ktorý kľúč používa konkrétne nasadenie.',
    'every_text_costs_money_codes_go_only_to_the__171894a6' => 'Každá SMS je spoplatnená. Kódy sa odosielajú iba do krajín uvedených nižšie a pre každé číslo, sieťovú adresu aj toto prostredie platia denné limity.',
    'every_text_costs_money_codes_go_only_to_the_countries_l_171894a6' => 'Každá SMS je spoplatnená. Kódy sa odosielajú iba do krajín uvedených nižšie a pre každé číslo, sieťovú adresu aj toto prostredie platia denné limity.',
    'everyone_in_this_organization_and_their_roles_one_built_35d8fefb' => 'Všetci v tejto organizácii a ich roly: každý má jednu vstavanú rolu a ľubovoľné aplikačné či vlastné roly',
    'everything_a_role_can_be_allowed_to_do_write_your_own_b_233ea6c4' => 'Všetko, čo môže rola povoľovať. Nižšie vytvorte vlastné oprávnenia bez programovania alebo nechajte aplikácie automaticky zaregistrovať ich vlastné.',
    'face_id_touch_id_windows_hello_or_a_security_key_turnin_6e23006c' => 'Face ID, Touch ID, Windows Hello alebo bezpečnostný kľúč. Vypnutie zachová už pridané prístupové kľúče na čas, keď túto možnosť opäť zapnete.',
    'filter_the_list_to_one_organization_to_scan_it_for_peop_6dbcc13b' => 'Vyfiltrujte jednu organizáciu a skontrolujte, kto už má konfliktnú dvojicu rolí. Zatiaľ neprebehla žiadna kontrola.',
    'for_a_secret_that_has_leaked_anything_still_using_it_fa_7b1c0246' => 'Pre tajný kľúč, ktorý unikol. Všetko, čo ho stále používa, okamžite prestane fungovať.',
    'for_development_refused_on_anything_but_the_origins_you_113f24ad' => 'Na vývoj. Rovnako ako v ostrej prevádzke sa odmieta použitie z iných zdrojov než z uvedených.',
    'give_your_app_the_feature_flags_scope_and_read_the_feat_a6908f11' => 'Udeľte aplikácii rozsah feature_flags a čítajte pole feature_flags z jej tokenu.',
    'give_your_apps_those_scopes_on_their_scopes_tab_tokens_97d115cd' => 'Udeľte aplikáciám tieto rozsahy na karte Rozsahy; ich tokeny budú uvádzať API ako príjemcu.',
    'grants_that_would_break_this_rule_are_blocked_from_now_1454bf59' => 'Pridelenia, ktoré by porušili toto pravidlo, sú odteraz blokované. Kto už má danú dvojicu, ponechá si ju — nájdete ho pomocou kontroly vyššie.',
    'have_the_app_declare_the_roles_it_understands_so_you_ca_9074afe0' => 'Nechajte aplikáciu deklarovať roly, ktoré podporuje, aby ste ich tu mohli prideľovať.',
    'holds_conflicting_roles_part1_part2_23b385ca' => 'Má konfliktné roly: :part1 :part2',
    'holds_part1_part2_6b1a0140' => 'Má :part1 :part2',
    'how_an_app_connects_is_fixed_at_registration_changing_i_0372baec' => 'Spôsob pripojenia aplikácie sa určuje pri registrácii. Zmena by zmenila význam prihlasovacích údajov, preto namiesto zmeny účelu tejto aplikácie zaregistrujte novú.',
    'how_long_an_access_token_for_this_app_is_acc_22748384' => 'Ako dlho sa prijíma prístupový token tejto aplikácie. Kratšia platnosť obmedzuje čas, počas ktorého môže aplikácia overujúca tokeny offline prijímať odvolaný token. Aplikácie používajúce introspekciu môžu odvolanie zistiť okamžite. Obnovovacie tokeny udržiavajú používateľov prihlásených medzi obnoveniami prístupových tokenov.',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Ako sa používatelia prihlasujú do :part1. Spočiatku platia predvolené nastavenia prostredia; zmeny tu ich môžu iba sprísniť.',
    'https_app_example_com_https_staging_example__ad77bfc7' => 'https://app.example.com
https://staging.example.com',
    'inherited_46b2e93c' => 'zdedené',
    'invoices_create_be35ad14' => 'invoices:create',
    'invoices_read_459482fd' => 'invoices:read',
    'its_rules_go_with_it_apps_asking_for_its_key_get_off_fr_aacd29e9' => 'Odstránia sa aj jeho pravidlá. Aplikácie, ktoré sa pýtajú na jeho kľúč, odteraz dostanú vypnutý stav; už vydané tokeny ho budú obsahovať do vypršania platnosti.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Odstránia sa aj jeho rozsahy. Aplikáciám zostanú ako ručne zadané rozsahy, ktoré už neplatia pre toto API; už vydané tokeny fungujú do vypršania platnosti.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Kľúče pre API správy prostredia: spravujte organizácie, členov, pozvánky, roly a aplikácie jedného prostredia z vlastného backendu. Každý kľúč má výslovne určené rozsahy oprávnení.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Roly a oprávnenia v tokene sú snímkou stavu v danom okamihu. Pred každou chránenou akciou získajte aktuálne rozhodnutie o prístupe od Cbox ID a v aplikácii overte prístup ku konkrétnemu zdroju. Samotný obsah tokenu nezohľadňuje neskoršie odobratie prístupu:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Vaše spôsoby prihlasovania a aktívne relácie. Prístupový kľúč je najbezpečnejšia a najrýchlejšia možnosť: zariadenie ho odomkne odtlačkom prsta alebo tvárou a nezostáva žiadne heslo, ktoré by sa dalo vylákať phishingom.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Každá akcia sa prijme tak, ako ju aplikácia odošle. Pridajte k akcii schému, aby sa jej udalosti pri prijatí overovali. Konzistentnosť protokolu sa zaisťuje pri zápise udalosti, nie až pri jej čítaní.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Každý kľúč API uložený v konfigurácii aplikácie alebo súbore prostredia je kľúč, ktorý nemôžete centrálne vymeniť ani rýchlo odobrať. Tu je uložený zašifrovane, prístup k nemu sa udeľuje jednotlivým aplikáciám a možno ho odvolať jedným kliknutím.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Tlačidlo sa prestane zobrazovať a prihlasovacie údaje sa vymažú. Ľuďom, ktorí sa cez poskytovateľa prihlásili, zostanú účty a naďalej môžu používať heslo. Ak chcete prihlasovacie údaje zachovať, poskytovateľa namiesto vymazania vypnite.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Opačný smer: Cbox ID odovzdáva vašich ľudí do ďalších produktov SaaS, ktoré firma používa, cez ich koncové body SCIM. Jedno miesto na udeľovanie a odoberanie prístupu namiesto samostatnej administrácie každého dodávateľa.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Vytvorí organizáciu, jej vlastníka, prvý produkt a produkčné prostredie tohto produktu. Vlastník dostane e-mailom odkaz na nastavenie vlastného hesla — nevyberáte ho za neho.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Dnes tu niekto ručne pridáva a odoberá ľudí. Pripojte adresár, ktorý už vaša firma spravuje, a obe činnosti sa budú vykonávať automaticky — vrátane odoberania, na ktoré sa najčastejšie zabúda.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Všetky tokeny, ktoré vydal, sa teraz odvolajú a na nové prihlásenia ho nemožno použiť. Aplikácia, ktorá tokeny overuje sama, ich prestane prijímať pri vypršaní ich platnosti, najneskôr na konci samotnej relácie.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Pri migrácii z iného systému môže aplikácia vo svojom manifeste vedľa rolí uviesť, kde je jej pôvodné prihlasovanie. Zobrazí sa tu na schválenie skôr, než začne čokoľvek vykonávať.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Vytvorte pravidlo, ktoré podľa vašich znalostí používateľov prístup povolí, vyžiada ďalšie overenie alebo ho zablokuje. Vyžadujte ďalšie overenie pri prihlásení z krajín, v ktorých nepôsobíte, alebo vyjmite kancelársku sieť z pravidiel frekvencie.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Overenie vlastnej domény, napríklad acme.com, umožní Cbox ID rozpoznať vašich ľudí podľa e-mailovej adresy a poslať ich priamo k vášmu poskytovateľovi, takže nikto nemusí vyberať správne prihlasovacie tlačidlo.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Poskytovateľ identity, ktorý importuje metadáta poskytovateľa služby, použije túto URL namiesto samostatného zadávania ID entity a URL ACS. Funguje ešte pred vyplnením konfigurácie na strane poskytovateľa identity.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Túto akciu nemožno vrátiť späť. Prihlasovacie údaje, členstvá a osobné údaje sa vymažú a účet sa pseudonymizuje. Ak ide o jediného vlastníka organizácie, najprv preveďte vlastníctvo.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Konáte ako táto osoba, v jej relácii a s jej oprávneniami. Prístup je obmedzený na 30 minút a iba na čítanie tam, kde to konzola dokáže vynútiť. Každá požiadavka sa zaznamená pod vaším menom.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Pozastavenie je jediná zmena vykonávaná na tejto stránke a možno ho zrušiť. Výber a otvorenie prostredia menia iba zobrazenie konzoly; v žiadnom prostredí nič nemenia.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Teraz sa ľudia prihlasujú pomocou prihlasovacích údajov uložených tu. Pripojte svojho poskytovateľa a budú používať existujúci firemný účet; hneď ako ho u poskytovateľa zakážete, stratia prístup aj tu.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Nevydáva sa nový tajný kľúč. Od ďalšieho pokusu vrátane opakovaní budú doručenia obsahovať hlavičky druhej schémy. Príjemca, ktorý nebol aktualizovaný, ich všetky odmietne.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Pošlite tento jednorazový odkaz správcovi ich poskytovateľa identity, ak ho nedostal e-mailom. Do vypršania platnosti funguje bez účtu. Skopírujte ho teraz — zobrazuje sa iba raz.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Softvér v tomto prostredí, ktorý čaká na povolenie človeka. Agent, ktorého kľúč vyžaduje schválenie, sa zastaví a požiada človeka, ktorý kľúč vytvoril. Odpovedzte tu alebo na telefóne.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Organizácia združuje používateľov, spôsoby prihlásenia a roly. Vytvorte ju vyššie alebo inicializujte prostredie prvou organizáciou a správcom na stránke Prostredia.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Pridajte túto osobu do niektorej z nižšie uvedených organizácií a udeľte jej v nej prístup. Ak aplikácie nemajú vlastné oddelenie organizácií, prideľte jej rolu správy a podpory platnú v celom prostredí.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Rola správy a podpory sa prideľuje vlastným pracovníkom v celom prostredí. Platí v každej organizácii a správcovia žiadnej organizácie ju nemôžu zobraziť ani zmeniť.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Žiadosti sa tu automaticky objavia, keď aplikácia alebo agent potrebuje vaše schválenie, aby mohol konať vo vašom mene. Dovtedy netreba nič robiť. Ak sa objaví žiadosť, ktorú ste nezačali, zamietnite ju.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'SMS sú najslabší druhý faktor: kto prevezme vaše telefónne číslo, dostane vaše kódy. Uprednostnite overovaciu aplikáciu alebo prístupový kľúč a SMS použite iba vtedy, ak tieto možnosti nemôžete využiť.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Predvolená vizuálna identita prostredia: vzhľad hostovanej prihlasovacej stránky, logo a favicon aj názov a odosielateľ zobrazovaní používateľom. Každá organizácia nastavenia zdedí, ak si neurčí vlastné.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Podrobnosti organizácie v cieľovom prostredí: členovia, SSO, domény, nároky a nedávna aktivita. Z tejto stránky možno zmeniť iba stav organizácie.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Všetky organizácie tejto inštalácie. Otvorte niektorú a prezrite si jej produkty a prostredia. Pozastavenie odhlási jej členov a zastaví overovanie identity vo všetkých prostrediach, ktoré vlastní.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Tieto udalosti posiela aplikácia: jedno volanie na dávku a každá udalosť uvádza organizáciu, v ktorej nastala. Ako prichádzajú, zobrazujú sa tu aj správcom danej organizácie.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Je dostupný na všetkých prihlasovacích stránkach prostredia. Vyberte organizáciu a nastavte jej vlastného poskytovateľa, ktorý na jej stránke nahradí poskytovateľa prostredia.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code otvorí prehliadač na prihlásenie tu a spýta sa, čo chcete povoliť. Nemusíte uchovávať žiadny kľúč. Rovnako s touto URL funguje každý klient MCP, ktorý sa prihlasuje cez OAuth.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Jedna organizácia tejto inštalácie: jej tím, projekty a všetky prostredia týchto projektov. Pozastavenie odhlási členov a zastaví overovanie identity vo všetkých týchto prostrediach.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Pre celé prostredie: do tejto aplikácie sa môže prihlásiť ktokoľvek s účtom v tomto prostredí, z ľubovoľnej organizácie. Ak takto široký prístup nechcete, uveďte organizáciu.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Prihlasovanie cez Entra ID, Okta alebo Google Workspace je dostupné v pláne Enterprise. Pre aktiváciu v tejto organizácii kontaktujte tím, ktorý sa stará o váš účet.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Kde ste prihlásení, čo môže konať vo vašom mene a čo sa dialo s vaším účtom. Ak uvidíte niečo, čo nespoznávate, ukončite danú reláciu a zmeňte heslo.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Koľko ľudí sa prihlásilo a ako často aplikácie volali API za posledných 30 dní. Údaje slúžia na prehľad o záťaži a hľadanie anomálií; nejde o faktúru.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Tento používateľ vlastní alebo spravuje organizáciu, a preto sa za neho nemožno vydávať. Vstup do takého účtu by mohol dať dotyčnému trvalú kontrolu nad organizáciou.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Kľúče API, ktorými sa vaše aplikácie a agenti preukazujú iným službám. Každá hodnota je v úložisku zašifrovaná, odovzdáva sa iba aplikáciám, ktorým udelíte prístup, a po uložení sa už nezobrazí.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Aplikácie žiadajúce o konanie v mene niektorého z vašich používateľov. Každý používateľ schvaľuje vlastné žiadosti. Tu žiadosť zamietnite iba vtedy, ak vyzerá ako zneužitie; zamietnutie sa zapíše do auditného protokolu.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Ako často načítavať údaje a ktoré vlastné polia personálneho systému kopírovať ku každej osobe, napríklad nákladové stredisko alebo lokalitu. Zmena polí spôsobí, že ďalší beh bude úplný.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Odkazy odovzdané správcovi IT tejto organizácie, ktoré stále poskytujú prístup. Odvolanie odkazu ho okamžite zneplatní; to, čo sa cez neho už nastavilo, zostane zachované.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Žiadosti agentov o konanie v mene používateľa sa tu zobrazujú, ako prichádzajú. Každý používateľ schvaľuje svoje vlastné. Táto stránka slúži na zamietnutie žiadostí, ktoré vyzerajú ako zneužitie.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Keď platia VŠETKY podmienky, Radar vykoná akciu tohto pravidla a ďalšie pravidlá už nevyhodnocuje. Pravidlá sa vyhodnocujú po zoznamoch povolených a blokovaných a pred vstavanými pravidlami.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Auditné udalosti, ktoré aplikácia posiela o všetkých obsluhovaných organizáciách, od najnovších. Udalosti každej organizácie tvoria vlastný reťazec hashov.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Všetko, čo má organizácia nastavené, aj to, čo zostáva urobiť. Kontrolný zoznam sleduje skutočný stav: krok sa sám označí ako hotový vo chvíli, keď je naozaj dokončený.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Ako správca pridajte aj overovaciu aplikáciu alebo prístupový kľúč. Prevzatím telefónneho čísla možno získať aj vaše SMS, preto nemôžu byť vaším jediným druhým faktorom.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Vymazanie tejto organizácie odstráni všetky jej projekty a prostredia. Na ochranu aktívnych poskytovateľov identity túto akciu nemožno vykonať samoobslužne. Pre pokračovanie kontaktujte podporu.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Okamžite stratí prístup ku všetkým stránkam platformy v tejto inštalácii a existujúce relácie prestanú fungovať pri ďalšej požiadavke. Tu môžete používateľa znova aktivovať.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Overené domény smerujú ľudí k vášmu vlastnému poskytovateľovi identity, čo je súčasť plánu Enterprise. Pre aktiváciu v tejto organizácii kontaktujte tím, ktorý sa stará o váš účet.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Oprávnenie určuje jednu činnosť, ktorú rola smie vykonať, napríklad vytváranie faktúr alebo čítanie prehľadov. Vlastné oprávnenia tu môžete vytvárať bez kódu a potom ich spájať do rolí. Aplikácie môžu svoje oprávnenia registrovať automaticky, aby zoznam zodpovedal skutočne vynucovaným pravidlám. Oprávnenia, ktoré vytvoríte, patria vám. Oprávnenia zdieľané prostredím môžete používať, ale nie meniť.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Pravidlá hesiel, uzamknutia, povinného druhého faktora a jednotného prihlasovania platné pri každom prihlásení. Pre celé prostredie sa nastavuje aj dostupnosť prístupových kľúčov a prihlasovacích odkazov a dĺžka relácie. Prostredie určuje základ, ktorý preberajú všetky organizácie. Organizácia môže pravidlá hesiel a druhého faktora sprísniť, nikdy však zmierniť.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Akcie, pri ktorých agenti v tomto prostredí čakajú na súhlas človeka. Agent, ktorého kľúč vyžaduje schválenie akcie, sa zastaví a požiada človeka, ktorý kľúč vytvoril. Ten môže odpovedať na telefóne alebo tu. Každý správca prostredia môže podozrivú požiadavku zamietnuť. Nižšie sú žiadosti aplikácií o konanie v mene používateľov, ktoré každý používateľ schvaľuje sám.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Relácie a tokeny tejto osoby sa zrušia. Jej prístupové kľúče, druhé faktory, členstvá, priradenia rolí, API tokeny, tajné údaje v trezore, zariadenia a všetky uložené kópie jej údajov sa odstránia. Z účtu zostane len pseudonymizovaný, deaktivovaný záznam. Aplikácie, ktoré odtiaľto synchronizujú osoby, dostanú pokyn na jej odstránenie. Auditný protokol zachová nepriehľadný identifikátor, nie meno ani adresu.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Všetko, čo ste schválili, vrátane zariadení alebo nástrojov príkazového riadka, z ktorých ste sa prihlásili.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Údaje, ktoré vaše systémy potrebujú uchovávať pri tejto organizácii. Riadky bez kľúča sa vynechajú.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Vyhodnocujú sa po vašich pravidlách. Každé spustené pravidlo sa zaznamená; rozhoduje najprísnejšie.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'Doručovanie sa obnoví. Záznamy vytvorené počas pozastavenia stále čakajú a odošlú sa v ďalšej dávke.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'Doručovanie sa okamžite zastaví a uložený prihlasovací údaj sa zničí. Auditné záznamy zostanú nezmenené.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Všetky prepojenia medzi Cbox ID a ďalšími systémami na jednom mieste: jednotné prihlasovanie, prihlásenie sociálnym účtom, synchronizácia adresárov a HR systémy, odchádzajúci provisioning, SAML aplikácie, webhooky, hooky, prenosy protokolov a dátové kanály. Z katalógu spustíte nastavenie ľubovoľného typu — každá karta otvorí príslušnú stránku. Zoznam pripojení ukazuje všetky existujúce prepojenia a ich stav, najprv tie s chybou.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Všetky spôsoby prihlasovania — heslo, prístupové kľúče, prihlasovací odkaz, sociálny účet, podnikové SSO a druhý faktor — vrátane toho, či sú zapnuté a kde sa nastavujú. Väčšinu určuje prostredie, SSO pripojenia patria jednotlivým organizáciám. Ak je metóda vypnutá alebo obmedzená nastavením inštalácie, stránka to uvádza aj s názvom príslušného nastavenia.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Agent je akýkoľvek softvér, ktorý v tomto prostredí koná s kľúčom na správu: AI asistent ako Claude Code alebo Cursor, interný bot alebo váš backend. Každému dajte vlastný kľúč iba s potrebnými rozsahmi. Určite, ktoré akcie majú čakať na schválenie, a kľúč zrušte, keď agent skončí alebo sa niečo bude zdať podozrivé.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'API je vaša služba, ktorá prijíma prístupové tokeny, napríklad https://api.example.com. Zaregistrujte ju s rozsahmi, ktoré rozpoznáva, aby ste ich mohli prideľovať. Určujete, o ktoré rozsahy môžu žiadať aplikácie registrované organizáciami v tomto prostredí. Token pre API obsahuje jeho adresu ako cieľového príjemcu, ktorého vaša služba overuje.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Ako auditná stopa opúšťa Cbox ID: plánovaný export posiela nové záznamy do SIEM alebo archívu každých päť minút. Denná úloha uchovávania vytvára kontrolný bod bez mazania údajov. Tu získate auditnú históriu jednej osoby pre žiadosť o prístup podľa GDPR alebo v konzole prostredia overíte, či exporty fungujú.',
    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Vytvorte prostredie v časti Platforma › Prostredia a jeho počty sa zobrazia tu.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'Všetky prostredia tejto inštalácie a ich podiel na celku',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'Všetky fronty úloh na pozadí tejto inštalácie a čas čakania najstaršej úlohy v každom z nich',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Všetky počítadlá využitia za toto obdobie a pôvodné kľúče príslušných metrík',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Vyhľadajte organizáciu alebo používateľa vo všetkých prostrediach, nielen v prostredí práve vybranom v konzole.',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Jeden dlhodobo bežiaci proces, php artisan queue:autoscale, spúšťa a zastavuje pracovné procesy, ktoré spracúvajú úlohy vo fronte.',
    'prefix_74feac5e' => 'Prefix',
    'account_menu_value0_6ab6a9a2' => 'Ponuka účtu — :value0',
    'acme_inc_ee60673d' => 'Acme Inc.',
