    'remove_value0_b8b38a7a' => 'Odobrať :value0?',
    'rename_value0_b709cc6f' => 'Premenovať :value0',
    'value0_not_included_in_this_organization_s_p_a6447bb1' => ':value0 Nie je súčasťou plánu tejto organizácie.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Žiadna prihlásená doména nezodpovedá hľadaniu. Skúste časť domény bez @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Tomuto názvu nezodpovedá žiadne pripojenie. Skúste iný hľadaný výraz.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Tomuto názvu nezodpovedá žiadny adresár. Skúste iný hľadaný výraz.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Hľadaniu nezodpovedá žiadna URL koncového bodu. Skúste iný výraz.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Týmto filtrom nezodpovedá žiadny záznam. Skúste všeobecnejší výraz alebo odstráňte filter.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Tomuto názvu nezodpovedá žiadny prúd protokolov. Skúste iné hľadanie.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Tomuto názvu nezodpovedá žiadne odchádzajúce pripojenie. Skúste iné hľadanie.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Všetky prvky značky, ktoré používatelia vidia, na jednej stránke: logo, favicon, farby, písmo a zaoblenie hostovanej prihlasovacej stránky so živým náhľadom, ako aj názov produktu, odosielateľ e-mailov a uvítací e-mail. Nastavte ich raz pre celé prostredie a všetky organizácie ich prevezmú alebo dajte jednej organizácii vlastný vzhľad na karte Vizuálna identita.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Každý projekt v organizácii má vlastný program a limit prostredí. Tu sú uvedené spolu s využitím za tento mesiac: organizácie, účtované pripojenia jednotného prihlasovania a prihlásenia. Cena zohľadňuje mesačne aktívnych používateľov a podnikové pripojenia, napríklad SSO a SCIM. V testovacích prostrediach sa za pripojenia neplatí.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Všetky API kľúče vytvorené ľuďmi v tejto organizácii pre jej aplikácie: držiteľ, aplikácia, oprávnenia a posledné použitie. Kľúč smie len to, čo jeho držiteľ, a po jeho odchode z organizácie prestane fungovať. Zrušte kľúče, ktoré unikli alebo sa už nepoužívajú. Každý si vlastné kľúče vytvára v časti Môj účet.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Pri migrácii z iného systému môže aplikácia požiadať o overenie e-mailu a hesla osoby, ktorá ešte nie je v Cbox ID, na starom prihlasovacom koncovom bode. Pred schválením ho otestujte. Prijatá osoba sa vytvorí tu a do starého systému sa už neposiela. Ak však tento koncový bod nefunguje, používatelia, ktorí ešte neboli prevedení, sa nemôžu prihlásiť.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Auditné udalosti, ktoré vaša aplikácia posiela pre každú obsluhovanú organizáciu: kto vo vašom produkte čo urobil a kedy. Uchovávajú sa oddelene pre každú organizáciu v reťazci hashov a zobrazujú sa jej správcom. Použite ich, keď organizácia požiada o auditný protokol svojho účtu. Definujte schémy, aby udalosti zostali konzistentné.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Žiadne budúce dočasné oprávnenie neumožní otvoriť tento tajný údaj. Odvolanie je okamžité a trvalé.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Žiadni aktívni agenti. Odvolané kľúče a kľúče s uplynutou platnosťou zostávajú v zozname na evidenčné účely.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Bez oprávnení — iba identifikuje držiteľa',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Kým túto možnosť nezapnete, nič sa pre nikoho nezmení. Najprv vyskúšajte prihlásenie.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Ukladá sa iba hash. Ak kľúč stratíte, odvolajte ho a vytvorte nový.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Iba tu uvedené aplikácie môžu získať dočasný prístup k tomuto tajnému údaju. Všetky ostatné požiadavky sa zamietnu.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Relácie na všetkých ostatných zariadeniach prestanú fungovať pri ďalšej požiadavke. Na tomto zariadení zostanete prihlásení.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Táto organizácia zatiaľ nemá členov. Nikto sa do nej nemôže prihlásiť, kým nebude pozvaný alebo pridaný prostredníctvom provisioningu.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Heslo sa tu nenastavuje. Používateľ dostane e-mailom prihlasovací odkaz a zvolí si spôsob prihlasovania.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Každý krok sa vyhodnocuje podľa aktuálneho stavu, takže sprievodca vždy ukazuje skutočnú situáciu tejto organizácie.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Skopírujte kľúč teraz a odovzdajte ho agentovi. Uchováva sa iba hash, takže kľúč sa zobrazuje len raz.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'E-mailové domény tejto organizácie, každá overená pomocou DNS TXT záznamu. Po overení domény môžete zapnúť povinné smerovanie na SSO: všetci s adresou v tejto doméne použijú podnikové SSO namiesto hesla. Skôr než sa spoľahnete na jednotné prihlasovanie, overte všetky domény používané vašimi ľuďmi.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Vlastný prístupový model aplikácie: typy prostriedkov, napríklad dokumenty a priečinky, vzťahy ako vlastník, editor a čitateľ a ich dedenie. Čitatelia priečinka môžu napríklad čítať všetky dokumenty v ňom. Aplikácia zapisuje vzťahy osôb k prostriedkom a pri každej požiadavke sa pýta, či používateľ smie upraviť daný dokument. Odpoveď určuje schéma.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Toto prostredie popri REST API poskytuje MCP server, štandardný spôsob, akým AI asistenti volajú nástroje. Vložte adresu a kľúč na správu do Claude Code, Cursor alebo iného MCP klienta. Agent smie presne to, čo povoľujú rozsahy kľúča, s rovnakými kontrolami a auditným protokolom ako v konzole.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Kľúč umožňuje vašim skriptom a integráciám volať API aplikácie vo vašom mene bez prihlásenia. Smie len to, čo v danej aplikácii smiete vy: pri obmedzení vášho prístupu ho stratí aj kľúč. Kľúč sa zobrazuje iba raz. Pri vytvorení ho skopírujte a okamžite zrušte, ak unikne alebo ho prestanete používať.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Provisioning sa zastaví a mapovania skupín sa odstránia. Vytvorení používatelia zostanú.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Provisioning sa okamžite zastaví a všetky mapovania skupín sa odstránia. Túto akciu nemožno vrátiť späť.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'Provisioning do cieľovej aplikácie sa okamžite zastaví. Túto akciu nemožno vrátiť späť.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'Provisioning do cieľovej aplikácie sa okamžite zastaví. Už vytvorení používatelia v nej zostanú.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Telefónne číslo bolo odstránené. Ostatné overovacie faktory a kódy na obnovenie používateľa zostávajú nezmenené.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'Už pripojení používatelia si ponechajú rozsahy, ktoré schválili, kým sa znova nepripoja.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Pôvody boli aktualizované. Zmena sa prejaví pri ďalšej požiadavke.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Túto hodnotu môžu používať iné systémy. Jej zmena zmení adresy URL, ktoré majú uložené.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Používatelia závislí od tohto poskytovateľa prídu o tento spôsob prihlásenia. Túto akciu nemožno vrátiť späť.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Projekt bol pozastavený. Jeho prostredia zostávajú aktívne, ale nové nemožno pridávať, kým projekt znova neaktivujete.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Definícia roly bola aktivovaná. Existujúci držitelia teraz používajú tieto oprávnenia.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Pravidlo bolo aktivované. Udelenia prístupu, ktoré by ho porušili, sú odteraz blokované.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Schéma bola uložená. Udalosti tejto akcie sa odteraz kontrolujú podľa nej.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Schéma bola uložená. Odteraz určuje výsledok každej kontroly.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Odmietať udalosti, ktorých akcia nemá schému. Zapnite, keď bude mať schému každá akcia odosielaná vašou aplikáciou.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Objekty sa zapisujú do prefix/yyyy/mm/dd/hh/batch.ndjson.gz, jedna udalosť na riadok.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Len pre úložisko kompatibilné s S3, napríklad MinIO alebo Cloudflare R2. Prázdna hodnota použije koncový bod AWS pre danú oblasť.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Zaregistrujte túto hodnotu u poskytovateľa ako povolené URI presmerovania, presne v uvedenej podobe.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooky, oznámenia o odhlásení pripojeným aplikáciám, aktualizácie rolí získavané z týchto aplikácií a e-maily vo fronte spracúvajú procesy frontu na pozadí, bez čakania používateľa. Ak žiadny proces nebeží, nič sa neodošle, hoci zvyšok konzoly vyzerá v poriadku. Na tejto stránke problém uvidíte.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Kontrola, pri ktorej prejdete, kto má akú rolu, a potvrdíte, či ju ešte potrebuje. Prístupy sa nenápadne hromadia: ľudia menia tímy a ponechávajú si staré oprávnenia. Kontrola umožňuje tieto prístupy odobrať. Odobratie sa vykoná pri uzavretí kontroly a celý priebeh sa zaznamená pre audítora.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Ak aplikácia neskôr uvedie inú URL, toto schválenie sa zruší a budete požiadaní znova. Zmena miesta, kam sa posielajú heslá, vyžaduje nové schválenie. Delegované prihlásenie slúži na prechod: keď v starom systéme zostane len málo ľudí, vypnite ho a pošlite tejto skupine obnovenie hesla.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Umožňuje prihlásenie existujúcim firemným účtom, napríklad Microsoft Entra ID, Okta alebo Google Workspace, namiesto samostatného hesla tu. Raz pripojíte poskytovateľa identity a overíte svoje e-mailové domény. Všetci používatelia týchto domén potom budú pri prihlásení smerovaní k poskytovateľovi.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Všetci ľudia s identitou v tomto prostredí bez ohľadu na organizácie, do ktorých patria. Otvorte osobu na obnovenie hesla či druhého faktora, ukončenie relácií, deaktiváciu účtu, zmenu organizácií a rolí alebo trvalé vymazanie na základe žiadosti o uplatnenie práva na vymazanie.',
