    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Využitie celej platformy naprieč všetkými prostrediami, nielen prostredím práve vybraným v konzole.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'Spôsob prihlasovania vlastníkov a prevádzkovateľov organizácií do Cbox ID sa nastavuje v konzole prostredia platformy.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Tieto rozširujúce body sa spúšťajú počas operácie, nie po nej, a ich odpoveď mení výsledok: váš endpoint môže doplniť údaje do tokenu alebo prihlásenie rovno odmietnuť. Priamo sa podieľajú na vykonaní operácie — pomalý alebo nefunkčný endpoint pocíti človek, ktorý sa pokúša prihlásiť.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Poskytovateľ identity tu sám vytvára, aktualizuje a deaktivuje osoby pomocou štandardu SCIM. Nástup alebo odchod zaznamenaný v personálnom systéme sa v priebehu sekúnd prejaví v aplikáciách, bez požiadaviek na podporu a zabudnutých účtov — čo je zvlášť dôležité pri odchode.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Počty organizácií, používateľov, pripojení jednotného prihlásenia, aplikácií a synchronizácií používateľov v tomto prostredí, každé s odkazom na príslušnú stránku. Skratky nižšie spúšťajú najčastejšie činnosti: vytvorenie organizácie, používateľa, pripojenia jednotného prihlásenia alebo aplikácie.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Rola označuje pracovnú zodpovednosť, ktorej vaše aplikácie rozumejú, napríklad „Editor“ alebo „Pracovník podpory“. Tu určujete, kto má akú rolu; každá aplikácia sama určuje jej oprávnenia. Roly osobu sprevádzajú vo všetkých pripojených aplikáciách, takže prístup udeľujete aj odoberáte na jednom mieste.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Pri zápise kopíruje každý záznam auditného denníka do nástrojov bezpečnostného tímu, napríklad systému SIEM. Nastavte cieľ, aby sa vyšetrovanie začínalo v nástrojoch, ktoré tím už používa, bez žiadosti o export. Doručenie prebehne aspoň raz, preto sa môžu objaviť duplicity.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Organizácia sa tu zobrazí, keď sa niekto zaregistruje. Môžete ju tiež vytvoriť pomocou voľby Nová organizácia vyššie.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Pridajte doménu e-mailových adries členov tejto organizácie, zverejnite záznam TXT a overte doménu.',
