    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Každé prepojenie umožňuje ľuďom pripojiť vlastný účet v službe ako GitHub, Google alebo Slack. Tokeny sú tu uložené šifrovane a priebežne obnovované. Oprávnené aplikácie si pri každom volaní služby v mene osoby vyžiadajú platný token a samy ho neukladajú.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Rola pre správu a podporu sa udeľuje vlastným pracovníkom, napríklad podpore alebo prevádzkovému tímu, pre celé prostredie. Platí v každej organizácii a správcovia organizácií ju nemôžu zobraziť, udeliť ani odobrať. Vlastná rola aplikácie udelená týmto spôsobom platí len pre danú aplikáciu.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Prostredie je úplne izolovaná služba identity s vlastnými používateľmi, kľúčmi, prihlásením a vydavateľom. Tu sú uvedené všetky prostredia tejto inštalácie aj organizácie, ktorým patria. Vytvorte prostredie, prepnite naň konzolu a pridajte prvú organizáciu a správcu.',
