    'the_hr_system_s_own_field_names_to_copy_onto_each_perso_2c74edb8' => 'Názvy polí personálneho systému, ktoré sa majú kopírovať ku každému používateľovi, jeden na riadok — napríklad nákladové stredisko alebo miesto.',
    'the_identifier_the_application_calls_itself_in_its_auth_afe05ddf' => 'Identifikátor, ktorým sa aplikácia označuje vo svojich požiadavkách AuthnRequests.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Telefón s nainštalovanou overovacou aplikáciou umožňuje odpovedať na žiadosti o schválenie a upozorní vás, keď sa niekto prihlási do vášho účtu. Raz ho zaregistrujte naskenovaním kódu. Ak telefón stratíte, ihneď ho tu odstráňte, aby už nemohol nič schvaľovať.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Organizácia je zázemie jednej registrovanej spoločnosti v tejto inštalácii a obsahuje jej projekty, prostredia a tím. Otvorte ju na prehliadanie produktov a prostredí alebo ju pozastavte: tým odhlásite členov a zastavíte prihlasovanie vo všetkých jej prostrediach.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Keď aplikácia alebo AI agent potrebuje váš súhlas na konanie vo vašom mene, nemôže sa vždy opýtať na obrazovke pred vami — preto žiada tu. Schvaľujte len žiadosti, ktoré ste sami začali, a overte, že zobrazený kód zodpovedá kódu na zariadení, ktoré žiadosť odoslalo.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Projekt predstavuje jeden z vašich produktov s vlastným plánom, prihlasovaním a prostrediami, napríklad produkčným a predprodukčným. Odtiaľto otvorte prostredie, ktoré chcete spravovať. Nový projekt vytvorte pri spustení produktu, ktorý sa má účtovať a prevádzkovať samostatne.',
    'send_this_endpoint_every_organization_s_events_in_this_ea696387' => 'Odosielať na tento koncový bod udalosti všetkých organizácií v tomto prostredí, nielen jednej.',
    'signature_scheme_changed_deliveries_are_signed_the_new_9a0fb26a' => 'Schéma podpisovania bola zmenená. Od ďalšieho pokusu sa doručenia podpisujú novým spôsobom.',
    'the_hook_stops_being_called_and_its_signing_secret_is_d_ad833a77' => 'Hook sa prestane volať a jeho tajný kľúč na podpisovanie sa zničí. Túto akciu nemožno vrátiť späť.',
    'the_bucket_in_the_path_rather_than_the_host_name_a_cust_070b78d0' => 'Bucket je v ceste namiesto názvu hostiteľa. Vlastný koncový bod tento formát už používa.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Každá aplikácia, ktorá prihlasuje osoby cez Cbox ID alebo volá jeho API, sa tu registruje a dostane vlastné prihlasovacie údaje. Vytvorte samostatnú registráciu pre každú aplikáciu a prostredie. Údaje nikdy nezdieľajte, aby ste ich mohli jednej aplikácii zneplatniť bez výpadku ostatných.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Vyhľadá organizáciu podľa názvu alebo identifikátora či používateľa podľa mena alebo e-mailu vo všetkých prostrediach tejto inštalácie, nielen v prostredí vybranom v konzole. Použite, keď niekto požiada o pomoc a neviete, v ktorom prostredí je.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Pozrite si aplikáciu presne tak ako jeden z jej používateľov: prihlásite sa v jeho mene s uvedeným dôvodom, najviac na hodinu. Aplikácia sa dozvie, kto ju skutočne používa, a nezíska možnosť reláciu predĺžiť. Auditný denník organizácie zaznamená, kto to urobil a prečo.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Projekt je jeden produkt IdP vlastnený touto organizáciou a patria k nemu prostredia. Kým organizácia nevytvorí projekt vo vlastnej konzole, nie je tu žiadne prostredie na výber ani otvorenie. Na tejto obrazovke nemožno vytvoriť projekt za organizáciu.',
    'sign_in_with_face_id_touch_id_windows_hello__97a33786' => 'Prihlasujte sa pomocou Face ID, Touch ID, Windows Hello alebo bezpečnostného kľúča — bez hesla.',
    'sign_ins_and_changes_to_your_password_passkeys_and_two_9e7da5c8' => 'Tu sa zobrazujú prihlásenia a zmeny hesla, prístupových kľúčov a nastavení dvojfaktorového overovania.',
    'text_message_codes_are_no_longer_offered_her_1a9ddf89' => 'SMS kódy tu už nie sú dostupné. Použite overovaciu aplikáciu alebo prístupový kľúč.',
    'that_device_stops_being_able_to_sign_you_in__5e148d22' => 'Toto zariadenie vás už nebude môcť prihlásiť. Na tejto stránke ho môžete znova pridať.',
    'that_request_is_no_longer_waiting_it_was_answered_used_80728be7' => 'Táto požiadavka už nečaká — bola vybavená, použitá alebo jej platnosť uplynula.',
    'the_agent_is_told_no_when_it_asks_again_and_has_to_star_c28d8870' => 'Pri ďalšom dopyte dostane agent zamietnutie a musí začať znova. Zamietnutie sa zaznamená do auditného protokolu.',
    'the_browser_tab_icon_on_your_sign_in_pages_a_square_png_04f6f405' => 'Ikona karty prehliadača na prihlasovacích stránkach. Štvorcový obrázok PNG, ICO alebo WebP do 256 KB.',
    'the_hosted_sign_in_s_look_logo_and_favicon_and_the_name_39304e21' => 'Vzhľad, logo a favicon hostovaného prihlasovania a názov a odosielateľ, ktoré používatelia vidia.',
    'sent_when_someone_s_account_is_created_leave_it_empty_f_c7c58d7f' => 'Odosiela sa pri vytvorení účtu. Ponechajte prázdne pre predvolenú hodnotu.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Len pre poskytovateľa, ktorý nezverejňuje podpisové kľúče (jwks_uri) v dokumente discovery. Inak sa kľúče načítajú odtiaľ vrátane ich obmien. Zadajte verejný kľúč PEM. Ukladá sa šifrovane a už sa nezobrazí; na zachovanie aktuálneho kľúča nechajte pole prázdne.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Niektoré dvojice rolí nikdy nesmie mať rovnaká osoba: kto zadá platbu, nemal by ju aj schvaľovať. Tieto dvojice určite tu. Cbox ID blokuje nové priradenia, ktoré by pravidlo porušili, a ukáže, kto už má konfliktnú dvojicu rolí.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'API kľúče a tokeny, ktoré aplikácie a agenti potrebujú pre ďalšie služby, uložené šifrovane tu namiesto konfigurácie každej aplikácie. Tajnú hodnotu zadáte raz a vybraným aplikáciám povolíte jej použitie. Už sa nezobrazí — ak ju stratíte, nahraďte ju novou.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Sprístupňuje endpointy identity prostredia na vašej doméne, napríklad login.example.com, namiesto našej. Vlastníctvo domény preukážete záznamom DNS TXT. Nastavte ju, ak majú ľudia pri prihlasovaní vidieť len vašu adresu.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'Názov organizácie, ktorá združuje projekty, prostredia a tím a zobrazuje sa v celej konzole. Odstránenie organizácie vyradí všetky prostredia používané na prihlasovanie. Preto sa vykonáva žiadosťou podpore, nie tlačidlom.',
    'the_claim_is_dropped_if_capture_was_on_people_on_this_d_17d5c40e' => 'Registrácia vlastníctva domény sa odstráni. Ak bolo vynútené SSO zapnuté, používatelia tejto domény sa vrátia k bežnému prihlasovaniu.',
    'this_domain_will_no_longer_route_its_users_through_this_281a9227' => 'Táto doména už nebude smerovať používateľov cez SSO tejto organizácie. Túto akciu nemožno vrátiť späť.',
    'this_client_can_no_longer_lease_the_secret_any_lease_it_c5728383' => 'Tento klient už nemôže získať dočasný prístup k tajnému údaju. Už udelené dočasné oprávnenia zostávajú platné do uplynutia platnosti.',
    'this_endpoint_stops_receiving_events_and_its_delivery_h_b6a65cf3' => 'Tento koncový bod prestane prijímať udalosti a jeho história doručovania sa odstráni. Túto akciu nemožno vrátiť späť.',
