    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Každá organizácia je spoločnosť alebo tím používajúci váš produkt, s vlastnými členmi, rolami, doménami a jednotným prihlásením. Vytvorte jednu pre každú registrovanú spoločnosť. Otvorte ju na správu členov, pozvánok a overených domén alebo na jej pozastavenie.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID odošle podpísanú správu na váš endpoint po udalosti, napríklad pridaní člena alebo zmene roly, aby vaše systémy mohli reagovať bez pravidelného dopytovania. Neúspešné doručenie sa opakuje. Udalosť už nastala: endpoint dostáva informáciu, ale nerozhoduje o výsledku.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Schéma určuje podobu udalostí akcie: aké typy cieľových objektov uvádzajú a čo obsahujú ich metaúdaje. Udalosti akcie so schémou sa kontrolujú pri prijatí. Bez schémy sa prijmú tak, ako boli odoslané, ak nie je zapnutý prísny režim.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Všetci správcovia tejto organizácie, ich vstavané roly — Vlastník, Správca, Vývojár, Člen alebo Prehliadajúci — a prostredia, ku ktorým majú prístup. Pozývajte osoby e-mailom a každej sprístupnite iba prostredia potrebné na jej prácu.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Umožnite používateľom aplikácií pripojiť vlastné účty GitHub, Google, Slack alebo Salesforce, aby aplikácie mohli volať ich API v mene používateľov. Tokeny sa tu ukladajú šifrovane a obnovujú; dočasný prístup k nim získajú iba oprávnené aplikácie.',
    'the_invitee_accepts_by_email_nobody_is_added_to_an_orga_04408aaf' => 'Pozvaný používateľ prijíma pozvánku e-mailom. Nikto nie je pridaný do organizácie bez svojho súhlasu.',
    'this_user_has_no_signed_in_sessions_right_now_they_appe_0ac73d09' => 'Tento používateľ momentálne nemá prihlásené relácie. Zobrazia sa tu, keď sa prihlási.',
    'this_user_is_held_at_a_password_change_they_cannot_reac_ce196382' => 'Tento používateľ musí zmeniť heslo. K ničomu sa nedostane, kým nenahradí heslo, ktoré ste mu vydali.',
    'user_created_they_have_no_way_to_sign_in_until_you_send_a612f0b1' => 'Používateľ bol vytvorený. Nemôže sa prihlásiť, kým mu nepošlete odkaz.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Údaje používateľa boli vymazané. Účet je pseudonymizovaný a výmaz je zaznamenaný v auditnom protokole ako user.erased.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Prevádzkovatelia platformy spravujú všetky organizácie a prostredia tejto inštalácie, nad úrovňou každej z nich. Prevádzkovateľa pridajte iba osobe, ktorá spravuje samotnú inštaláciu, a pozastavte ho, keď túto prácu prestane vykonávať.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Všetky organizácie v prostredí vybranom v konzole, usporiadané ako strom predajcov, nimi spravovaných organizácií a ich podjednotiek. Tu môžete organizáciu vytvoriť, pozastaviť alebo presunúť pod inú nadradenú organizáciu.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Prihlásenia, vydané tokeny, noví používatelia a registrácie dvojfaktorového overovania po dňoch za posledných 30 dní, ak inštalácia neurčuje iné obdobie. Stránka zostane prázdna, kým prevádzkovateľ inštalácie nenastaví úložisko analytických údajov.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Nastavte toto ako politiku dôveryhodnosti roly (IAM › Roles › Trust relationships). Platforme umožní prevziať rolu len po predložení externého ID tohto prúdu, takže nikto iný na platforme nemôže nasmerovať prúd na vašu rolu.',
