    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Všetky prehliadače a zariadenia prihlásené do vášho účtu, aplikácie oprávnené konať vo vašom mene a posledné prihlásenia aj zmeny zabezpečenia. Ak niektorú aktivitu nespoznávate, odhláste danú reláciu alebo odoberte aplikácii prístup a potom zmeňte heslo.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Každá zmena v tejto organizácii: kto čo urobil, s akým objektom a kedy. Záznamy sú prepojené reťazcom hashov, takže odstránenie alebo úprava záznamu reťazec naruší a dá sa zistiť. Zámerne iba na čítanie — tento záznam odovzdávate audítorovi.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Pri takmer všetkých poskytovateľoch nechajte prázdne: ID tokeny sa overujú podpisovými kľúčmi zverejnenými v dokumente discovery (jwks_uri), vrátane ich obmien. Verejný kľúč PEM poskytovateľa vložte len vtedy, ak žiadny nezverejňuje.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Prihlásenia a požiadavky, ktoré Cbox ID vyhodnotil ako dostatočne rizikové na označenie, od najnovších, so skóre a jeho dôvodmi. Pozrite sa sem po náraste neúspešných prihlásení alebo keď niekto nahlási prihlásenie, ktoré nevykonal.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Toto prostredie ponúka server MCP popri REST API. Pripojte agenta s kľúčom na správu a bude môcť robiť presne to, čo dovoľujú rozsahy kľúča, s rovnakými kontrolami, schvaľovaním a auditným denníkom ako konzola.',
    'nothing_recorded_matches_these_filters_widen_the_range_804705cd' => 'Žiadny záznam nezodpovedá týmto filtrom. Rozšírte rozsah alebo odstráňte filter.',
