    'the_ten_organizations_with_the_most_members_and_the_env_1c7ea5a5' => 'Desať organizácií s najväčším počtom členov a prostredie, do ktorého každá patrí',
    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Kto je práve prihlásený ako tento používateľ. Radar ukazuje, prečo bolo prihlásenie povolené, vyžadovalo dodatočné overenie alebo bolo zablokované.',
    'what_this_organization_s_sign_in_is_wired_to_read_from_cde71601' => 'Na čo je napojené prihlasovanie tejto organizácie podľa skutočnej konfigurácie.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Vlastný poskytovateľ organizácie nahradí poskytovateľa prostredia na jej prihlasovacej stránke. Uvedené sú aj organizácie, ktoré poskytovateľa prostredia vypli. Tým sa len odstráni tlačidlo zo stránky; prístup touto metódou zablokuje až vyžadovanie SSO.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Aplikácie s vlastným zoznamom používateľov strácajú súlad, len čo niekto príde alebo odíde. Pripojenie SCIM im priebežne odovzdáva každú zmenu vrátane odchodov, na ktoré sa najľahšie zabúda.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Nasmerujte poskytovateľa identity na náš endpoint SCIM, pripojte Google Workspace alebo Microsoft Entra či personálny systém — Workday, BambooHR, Rippling, HiBob alebo Personio. Údaje o ľuďoch budeme načítavať podľa plánu.',
