    'applications_you_approve_a_command_line_a_device_anothe_9ae677c4' => 'Tu sa zobrazujú vami schválené aplikácie — nástroj príkazového riadka, zariadenie alebo iný produkt prihlasujúci cez Cbox ID. Ktorejkoľvek môžete odobrať prístup.',
    'as_an_administrator_set_up_an_authenticator__17d31053' => 'Ako správca najprv nastavte overovaciu aplikáciu alebo prístupový kľúč. Potom možno pridať telefónne číslo ako záložnú metódu.',
    'attempts_this_rule_decided_are_decided_by_the_next_matc_ebfc6722' => 'Od ďalšieho pokusu bude prípady rozhodované týmto pravidlom vyhodnocovať ďalšie zodpovedajúce pravidlo alebo vstavané pravidlá.',
    'called_synchronously_while_somebody_waits_at_the_sign_i_cf697019' => 'Volá sa synchrónne, kým osoba čaká na prihlasovacej obrazovke. Pri každej požiadavke overte hlavičku X-Cbox-Signature.',
