    'this_browser_cannot_create_a_passkey_so_ther_2fac1ac0' => 'Tento prehliadač nevie vytvoriť prístupový kľúč, takže tu nemožno pridať nový. Existujúce kľúče sú uvedené nižšie a možno ich odstrániť.',
    'they_lose_this_role_in_every_organization_at_once_apps_2750f7e3' => 'Osoba stratí túto rolu vo všetkých organizáciách naraz. Priebežné kontroly oprávnení zohľadnia zmenu pri ďalšej chránenej akcii; údaje v existujúcich tokenoch zachytávajú stav pri vydaní. Nikto nie je odhlásený.',
    'they_lose_this_role_in_every_organization_at_once_apps_39477fda' => 'Osoba stratí túto rolu vo všetkých organizáciách naraz. Priebežné kontroly oprávnení zohľadnia zmenu pri ďalšej chránenej akcii; údaje v existujúcich tokenoch zachytávajú stav pri vydaní. Nikto nie je odhlásený.',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Správcovský kľúč koná iba vo vlastnom prostredí. Exportujte predlohu aplikácie (GET /apps/{id}/blueprint) a zaregistrujte ju pomocou kľúča druhého prostredia (POST /apps s `blueprint`).',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Vyberte SCIM, ak nám poskytovateľ odosiela údaje, Google Workspace alebo Entra, ak ich máme načítavať my, alebo váš personálny systém — Workday, BambooHR, Rippling, HiBob či Personio — aby používatelia pribudli v deň nástupu.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Kľúče príznakov funkcií zapnutých pre daného človeka v organizácii, do ktorej sa prihlásil, vloží do prístupového tokenu, ID tokenu a UserInfo ako tvrdenie `feature_flags`.',
    'puts_everything_userinfo_answers_for_the_app_s_scopes_e_db47369d' => 'Vloží do ID tokenu všetko, čo UserInfo vracia pre rozsahy aplikácie (e-mail, meno, roly, oprávnenia, organizácie), takže aplikácia môže pri prihlásení vynechať volanie UserInfo. Iba pre aplikáciu, ktorá pri odhlásení posiela `id_token_hint` metódou POST alebo ho neposiela vôbec: token v adrese URL sa zapisuje do prístupových protokolov.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Tlačidlo zmizne z prihlasovacej stránky tejto organizácie; tlačidlo prostredia ho nenahradí. Prihlasovacie údaje zostanú uložené, takže ho môžete znova zapnúť.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Tieto prihlasovacie údaje vyžadujú pre danú akciu schválenie človeka, no nie je evidovaný nikto, kto ho môže udeliť. Vykonajte akciu v konzole alebo tam vytvorte kľúč, ktorého vlastník ju môže schváliť.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Tento endpoint patrí prostrediu a spúšťa sa pre každú jeho organizáciu. Zobrazuje sa tu, pretože zasahuje do vašich prihlásení; spravuje ho prevádzkovateľ.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'E-mail sa teraz nepodarilo odoslať — táto inštalácia sa nevie spojiť s poštovým serverom. Skúste to neskôr; správca môže adresu potvrdiť aj príkazom `php artisan cbox-id:users:confirm-email`.',
    'when_an_app_or_agent_needs_your_go_ahead_to_act_as_you_3a85a2a9' => 'Keď aplikácia alebo agent potrebuje váš súhlas na konanie vo vašom mene, požiada tu. Schvaľujte len žiadosti, ktoré ste sami začali.',
    'whether_the_background_work_of_this_install_webhooks_si_0647da12' => 'Overte, či sa úlohy na pozadí tejto inštalácie — webhooky, oznámenia o odhlásení pripojeným aplikáciám a e-maily vo fronte — skutočne odosielajú.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Potrebujete prihlasovacie údaje z vlastného účtu u poskytovateľa, zvyčajne ID a tajnú hodnotu klienta. Apple namiesto nej vydáva podpisový kľúč.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'Váš endpoint sa volá počas operácie a jeho odpoveď mení výsledok: môže pridať údaje do tokenu alebo odmietnuť prihlásenie.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Vaše endpointy dostávajú podpísanú správu po udalosti, aby systémy mohli reagovať bez neustáleho dopytovania.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'Názov, domény a predvolené nastavenia organizácie. Zmeny platia pre všetky osoby prihlasujúce sa cez túto organizáciu.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'Vlastné prihlasovacie údaje u jednotlivých poskytovateľov, ponúkané na všetkých prihlasovacích stránkach tohto prostredia. Dedia ich všetky jeho organizácie.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Vlastné prihlasovacie údaje u jednotlivých poskytovateľov, ponúkané všetkým v tomto prostredí. Každá organizácia ich dedí.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Prijímač uchováva rovnakú tajnú hodnotu a používa ju presne v uvedenej podobe vrátane predpony whsec_ ako HMAC kľúč pre X-Cbox-Signature.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Vaša prihlasovacia stránka nesie vaše logo a farby. Ľudia do nej zadávajú heslo — mala by vyzerať ako vaša služba, nie naša.',
    'your_organization_its_projects_team_keys_and_billing_si_152a2f42' => 'Vaša organizácia: projekty, tím, kľúče a fakturácia. Prihlasovanie do aplikácií sa nastavuje v konzole každého prostredia.',
    'a_management_key_reads_and_writes_this_envir_aba5f345' => 'Správcovský kľúč číta a mení organizácie a používateľov tohto prostredia cez API a jeho hodnota sa zobrazí iba raz.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'V aplikácii :part1 nemáte žiadne oprávnenia, takže kľúč by vás iba identifikoval a nič ďalšie neumožnil.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Ponúka sa iba to, čo sami smiete robiť v aplikácii :part1. Ak neskôr stratíte oprávnenie, stratí ho aj kľúč.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Rozsah „:part1“ bol odstránený. Aplikácie, ktoré ho mali, si ho ponechajú ako ručne zadaný rozsah, ktorý už neposkytuje prístup k tomuto API.',
