    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Vloží ROLY človeka do ID tokenu pod názvom `groups`, ktorý očakávajú Kubernetes, Grafana, Vault a väčšina starších služieb SaaS. V tejto konzole nie je pojem skupina: vytvorte Rolu s názvom, ktorý aplikácia očakáva, a objaví sa tu.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Túto ikonu stránky nemožno použiť. Odošlite samotný obrázok ako URI data: v base64 (data:image/png;base64,…). Vzdialené URL obrázkov nie sú povolené: obrázok na prihlasovacej stránke načíta každý návštevník a externá URL by jeho prevádzkovateľovi prezradila, kto stránku navštívil.',
