    'copying_an_app_registers_it_in_another_envir_b6eb3523' => 'Kopírovanie aplikácie ju zaregistruje v inom prostredí s novým tajným údajom klienta, zobrazeným iba raz na ďalšej obrazovke.',
    'creating_an_app_issues_a_client_secret_shown_2840959a' => 'Vytvorenie aplikácie vydá tajný údaj klienta, ktorý sa zobrazí iba raz na ďalšej obrazovke a až do rotácie umožňuje autentifikáciu ako táto aplikácia.',
    'each_redirect_uri_must_use_https_http_is_all_5445c31e' => 'Každá URI presmerovania musí používať https (http je povolené iba na localhost), napríklad https://app.example.com/callback.',
