    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — relácie, prístupové kľúče, druhé faktory, profily poskytovateľov identity, adresárové údaje, vydané tokeny, priradenia rolí aj história auditu zostanú zachované. Osobu možno znova aktivovať.',
