    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Týmito metódami sa do tejto konzoly neprihlasuje. Správcovia sa prihlasujú cez Cbox ID na :part2 pomocou jeho prihlasovacích metód.',
